Dado el siguiente código para un trigger, ¿Qué hará si se actualiza el salario de un empleado en la tabla Empleados?
CREATE TRIGGER Trg_UpdateSalario
AFTER UPDATE ON Empleados
FOR EACH ROW
BEGIN
IF OLD.Salario < NEW.Salario THEN
INSERT INTO LogSalarios (EmpleadoID, SalarioAntiguo, SalarioNuevo, FechaCambio)
VALUES (OLD.ID, OLD.Salario, NEW.Salario, NOW());
END IF;
END;

